exercises.solution:
#include <stdio.h>

int main(void) {
    char buf[64];
    snprintf(buf, sizeof buf, "{\"Name\":\"%s\",\"Age\":%d}", "Alice", 30);
    puts(buf);
    return 0;
}

#include <stdio.h>

int main(void) {
    const char *json = "{\"Name\":\"Bob\",\"Age\":25}";
    char name[16];
    int age;
    sscanf(json, "{\"Name\":\"%15[^\"]\",\"Age\":%d}", name, &age);
    printf("%s %d\n", name, age);
    return 0;
}

