#include <stdio.h>

int main(void) {
    char buf[64];
    snprintf(buf, sizeof buf, "{\"Server\":\"%s\"}", "api.example.com");
    puts(buf);
    return 0;
}

#include <stdio.h>

int main(void) {
    char json[96];
    snprintf(json, sizeof json, "{\"id\":%d,\"name\":\"%s\",\"price\":%.2f}", 1, "Laptop", 999.99);
    int id; char name[16]; double price;
    sscanf(json, "{\"id\":%d,\"name\":\"%15[^\"]\",\"price\":%lf}", &id, name, &price);
    printf("Original: {%d %s %.2f}\n", 1, "Laptop", 999.99);
    printf("Recovered: {%d %s %.2f}\n", id, name, price);
    return 0;
}

#include <stdio.h>

int main(void) {
