    puts(buf);
    return 0;
}

#include <stdio.h>

int main(void) {
    char buf[128];
    snprintf(buf, sizeof buf,
        "[{\"Name\":\"%s\",\"Age\":%d},{\"Name\":\"%s\",\"Age\":%d}]",
        "Alice", 30, "Bob", 25);
    puts(buf);
    return 0;
}

